	Policy() ProposerPolicy
}

// Validator is an interface which defines the standard for block validation. It
// is only responsible for validating block contents, as the header validation is
// done by the specific consensus engines.
type Validator interface {
	// ValidateBody validates the given block's content.
	ValidateBody(block *types.Block) error

	// ValidateState validates the given statedb and optionally the receipts and
	// gas used.
	ValidateState(block *types.Block, state *state.StateDB, receipts types.Receipts, usedGas uint64) error
}

func initializeBase(govBaseAddress common.Address, param map[string]string) ([]params.StateParam, error) {
	sp := make([]params.StateParam, 0)

	quorum := uint64(0)
	if quorumStr, ok := param[GOV_BASE_PARAM_QUORUM]; ok {
		var err error
		quorum, err = strconv.ParseUint(quorumStr, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("`systemContracts.govBase.params.quorum`: %w", err)
		}

		// Validate quorum is greater than 0
		if quorum == 0 {
			return nil, fmt.Errorf("`systemContracts.govBase.params.quorum` must be greater than 0")
		}

		sp = append(sp,
			params.StateParam{
				Address: govBaseAddress,
				Key:     common.HexToHash(SLOT_GOV_BASE_quorum),
				Value:   common.BigToHash(big.NewInt(int64(quorum))),
			},
		)
	}

	if expiryStr, ok := param[GOV_BASE_PARAM_EXPIRY]; ok {
		expiry, err := strconv.ParseUint(expiryStr, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("`systemContracts.govBase.params.expiry`: %w", err)
		}
		sp = append(sp,
			params.StateParam{
				Address: govBaseAddress,
				Key:     common.HexToHash(SLOT_GOV_BASE_proposalExpiry),
				Value:   common.BigToHash(big.NewInt(int64(expiry))),
			},
		)
	}

	if membersStr, ok := param[GOV_BASE_PARAM_MEMBERS]; ok {
		memberAddresses := splitAndTrim(membersStr, ",")

		// Pre-validate and deduplicate members
		uniqueMembers := make([]common.Address, 0)
		seen := make(map[common.Address]struct{})
		for _, addrStr := range memberAddresses {
			member := common.HexToAddress(addrStr)

			// Validate zero address
			if member == (common.Address{}) {
				return nil, fmt.Errorf("`systemContracts.govBase.params.members` contains invalid zero address")
			}

			// Add to slice only if not seen before
			if _, exists := seen[member]; !exists {
				seen[member] = struct{}{}
				uniqueMembers = append(uniqueMembers, member)
			}
		}

		// Check quorum after deduplication
		if quorum > 0 && uint64(len(uniqueMembers)) < quorum {
			return nil, fmt.Errorf("`systemContracts.govBase.params.quorum` (%d) must not be greater than unique member count (%d)", quorum, len(uniqueMembers))
		}

		// Enforce maximum member limit (matches Solidity MAX_MEMBER_INDEX)
		const MAX_MEMBERS = 255
		if len(uniqueMembers) > MAX_MEMBERS {
			return nil, fmt.Errorf("`systemContracts.govBase.params.members` count (%d) exceeds maximum allowed (%d)", len(uniqueMembers), MAX_MEMBERS)
		}

		// Quorum validation matching GovBase.sol logic
		// This ensures consistency between genesis initialization and smart contract behavior
		// Only validate if quorum is explicitly provided (quorum > 0)
		if quorum > 0 {
			memberCount := uint64(len(uniqueMembers))
			if memberCount == 1 {
				// Single member governance: quorum must be exactly 1
				// WARNING: Single-member governance is centralized and not recommended for production
				if quorum != 1 {
					return nil, fmt.Errorf("`systemContracts.govBase.params.quorum` must be exactly 1 for single-member governance, got %d", quorum)
				}
			} else {
				// Multi-member governance: require at least 2 approvals (proposer + 1 reviewer)
				// This prevents any single member from executing proposals without peer review
				// Security: quorum=1 would allow single-member unilateral decisions
				if quorum < 2 {
					return nil, fmt.Errorf("`systemContracts.govBase.params.quorum` (%d) must be at least 2 for multi-member governance (member count: %d)", quorum, memberCount)
				}
			}
		}

		membersSlot := common.HexToHash(SLOT_GOV_BASE_members)
		versionedMemberListSlot := common.HexToHash(SLOT_GOV_BASE_versionedMemberList)
		versionSlot := common.HexToHash(SLOT_GOV_BASE_version)
		memberIndexByVersionSlot := common.HexToHash(SLOT_GOV_BASE_memberIndexByVersion)
		quorumByVersionSlot := common.HexToHash(SLOT_GOV_BASE_quorumByVersion)

		versionStr, ok2 := param[GOV_BASE_PARAM_MEMBER_VERSION]
		if !ok2 {
			return nil, fmt.Errorf("`systemContracts.govBase.params.memberVersion` is required when `systemContracts.govBase.params.members` is set")
		}
		versionInt, err := strconv.ParseUint(versionStr, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("`systemContracts.govBase.params.memberVersion`: %w", err)
		}
		version := new(big.Int).SetUint64(versionInt)

		// joinedAt is set to 0 for all initial members.
		// We do not use the current time in the genesis (configuration).
		// This is because it makes the genesis generation non-deterministic.
		memberData := Member{
			IsActive: true,
			JoinedAt: 0,
		}.ToHash()

		currentIdx := uint64(0)
		// Use uniqueMembers slice for iteration
		for _, member := range uniqueMembers {
			// Additional overflow check (defensive programming)
			if currentIdx >= MAX_MEMBERS {
				return nil, fmt.Errorf("member index overflow: currentIdx (%d) >= MAX_MEMBERS (%d)", currentIdx, MAX_MEMBERS)
			}
			sp = append(sp,
				// Set member active status and joinedAt timestamp
				params.StateParam{
					Address: govBaseAddress,
					Key:     CalculateMappingSlot(membersSlot, member),
					Value:   memberData,
				},
				// Add member to versionedMemberList[version][currentIdx]
				params.StateParam{
					Address: govBaseAddress,
					Key:     CalculateDynamicSlot(CalculateMappingSlot(versionedMemberListSlot, version), new(big.Int).SetUint64(currentIdx)),
					Value:   common.BytesToHash(member.Bytes()),
				},
				// Set memberIndexByVersion[version][member] = currentIdx + 1
				// Note: Index is 1-based (0 means not a member)
				params.StateParam{
					Address: govBaseAddress,
					Key:     CalculateMappingSlot(CalculateMappingSlot(memberIndexByVersionSlot, version), member),
					Value:   common.BigToHash(new(big.Int).SetUint64(currentIdx + 1)),
				},
			)
			currentIdx++
		}

		if currentIdx > 0 {
			sp = append(sp,
				params.StateParam{
					Address: govBaseAddress,
					Key:     CalculateMappingSlot(versionedMemberListSlot, version),
					Value:   common.BigToHash(new(big.Int).SetUint64(currentIdx)),
				},
			)
		}
		sp = append(sp,
			params.StateParam{
				Address: govBaseAddress,
				Key:     versionSlot,
				Value:   common.BigToHash(version),
			},
		)

// It
// - validates PREPARE message digest matches the current block proposal
// - accumulates valid PREPARE message until reaching quorum
// - when quorum is reached update states to "Prepared" and broadcast COMMIT
func (c *Core) handlePrepareMsg(prepare *wbfmessage.Prepare) error {
	logger := c.currentLogger(true, prepare).New()

	logger.Debug("WBFT: handle PREPARE message", "prepares.count", c.current.WBFTPrepares.Size(), "quorum", c.valSet.QuorumSize())

	// Check digest
	if prepare.Digest != c.current.Proposal().Hash() {
		logger.Warn("WBFT: invalid PREPARE message digest")
		return errInvalidMessage
	}

	// Check prepareSeal
	block, ok := c.current.Proposal().(*types.Block)
	if !ok {
		logger.Warn("WBFT: failed to cast proposal from PREPARE message to *types.Block")
		return errInvalidMessage
	}

	if verifySeal(c.valSet, block.Header(), uint32(prepare.CommonPayload.Round.Uint64()), SealTypePrepare,
		prepare.PrepareSeal, prepare.Source()) != nil {
		logger.Warn("WBFT: failed to verify seal from PREPARE message", "number", block.Header().Number, "from", prepare.Source())
		return errInvalidMessage
	}

	// Save PREPARE messages
	if err := c.current.WBFTPrepares.Add(prepare); err != nil {
		logger.Error("WBFT: failed to save PREPARE message", "err", err)
		return err
	}

	logger = logger.New("prepares.count", c.current.WBFTPrepares.Size(), "quorum", c.valSet.QuorumSize())

	// Change to "Prepared" state if we've received quorum of PREPARE messages
	// and we are in earlier state than "Prepared"
	if (c.current.WBFTPrepares.Size() >= c.valSet.QuorumSize()) && c.state.Cmp(StatePrepared) < 0 {
		logger.Info("WBFT: received quorum of PREPARE messages")

		// Accumulates PREPARE messages
		c.current.preparedRound = c.currentView().Round
		c.WBFTPreparedPrepares = make([]*wbfmessage.Prepare, 0)
		for _, m := range c.current.WBFTPrepares.Values() {
			c.WBFTPreparedPrepares = append(
				c.WBFTPreparedPrepares,
				wbfmessage.NewPrepareWithSigAndSource(
					m.View().Sequence, m.View().Round, m.(*wbfmessage.Prepare).Digest, m.Signature(), m.Source(), m.(*wbfmessage.Prepare).PrepareSeal))
		}

		if c.current.Proposal() != nil && c.current.Proposal().Hash() == prepare.Digest {
			logger.Trace("WBFT: PREPARE message matches proposal", "proposal", c.current.Proposal().Hash(), "prepare", prepare.Digest)
			c.current.preparedBlock = c.current.Proposal()
		}

		c.setState(StatePrepared)
		c.broadcastCommit()
	} else {
		logger.Trace("WBFT: accepted PREPARE messages")
	}

	return nil
}

/// @dev Add new governance member with quorum update
/// @param newMember Address of new member to add
/// @param newQuorum New quorum requirement (1 for single member, ≥2 for multiple)
///
/// @notice Member addition flow (Checks-Effects-Interactions):
/// 1. Checks: Validate member status, address, and quorum requirements
/// 2. Effects: Create new version snapshot, update member mappings and quorum
/// 3. Interactions: Call _onMemberAdded hook for derived contract logic
///
/// @notice Quorum rules: Single member requires quorum=1, multiple members require quorum≥2
/// @notice Member limit: MAX_MEMBER_INDEX (255) enforced via MemberIndexOverflow
///
/// @notice Security consideration: _onMemberAdded is called after state changes
///         Derived contracts must avoid external calls in _onMemberAdded to prevent
///         cross-function reentrancy attacks
/// @notice Reentrancy protection: Caller (_executeProposal) has nonReentrant guard
function _addMember(address newMember, uint32 newQuorum) internal {
    // CHECKS: Validate member and address
    if (members[newMember].isActive) revert AlreadyAMember();
    if (newMember == address(0)) revert InvalidMemberAddress();

    // EFFECTS: Create new version snapshot
    (address[] storage newSnapshot, address[] storage oldSnapshot, uint256 newVersion) = _prepareNextMemberVersion();
    uint256 oldLength = oldSnapshot.length;
    uint256 newMemberCount = oldLength + 1;
    if (oldLength >= MAX_MEMBER_INDEX) revert MemberIndexOverflow();

    // CHECKS: Validate quorum requirements
    if (newMemberCount == 1) {
        if (newQuorum != 1) revert InvalidQuorum();
    } else {
        if (newQuorum < 2 || newQuorum > newMemberCount) revert InvalidQuorum();
    }

    // EFFECTS: Copy existing members to new snapshot
    for (uint256 i = 0; i < oldLength; i++) {
        address existing = oldSnapshot[i];
        newSnapshot.push(existing);
        // Safe cast: member count limited to MAX_MEMBER_INDEX (255) < uint32.max
        // forge-lint: disable-next-line(unsafe-typecast)
        _memberIndexByVersion[newVersion][existing] = uint32(i + 1);
    }

    // EFFECTS: Add new member to snapshot and update state
    newSnapshot.push(newMember);
    // Safe cast: oldLength < MAX_MEMBER_INDEX (255) < uint32.max
    // forge-lint: disable-next-line(unsafe-typecast)
    _memberIndexByVersion[newVersion][newMember] = uint32(oldLength + 1);

    members[newMember] = Member({ isActive: true, joinedAt: uint32(block.timestamp) });

    uint32 oldQuorum = quorum;
    quorum = newQuorum;

    emit MemberAdded(newMember, newSnapshot.length, newQuorum);
    emit QuorumUpdated(oldQuorum, newQuorum);

    // INTERACTIONS: Call hook for derived contract logic (avoid external calls here)
    _onMemberAdded(newMember);

    _quorumByVersion[newVersion] = newQuorum;
}

/// @dev Change governance quorum requirement
/// @param newQuorum New quorum value to set
///
/// @notice Quorum change flow (Checks-Effects):
/// 1. Checks: Validate quorum requirements based on current member count
/// 2. Effects: Update quorum value and emit QuorumUpdated event
///
/// @notice Quorum rules: Single member requires quorum=1, multiple members require quorum≥2
/// @notice Quorum cannot exceed current member count
///
/// @notice Reentrancy protection: Caller (_executeProposal) has nonReentrant guard
function _changeQuorum(uint32 newQuorum) internal {
    uint256 memberCount = versionedMemberList[memberVersion].length;

    // CHECKS: Validate quorum requirements
    if (memberCount == 1) {
        if (newQuorum != 1) revert InvalidQuorum();
    } else {
        if (newQuorum < 2 || newQuorum > memberCount) revert InvalidQuorum();
    }

    // Update quorum value
    uint32 oldQuorum = quorum;
    quorum = newQuorum;

    emit QuorumUpdated(oldQuorum, newQuorum);

    // Update snapshot for current version
    _quorumByVersion[memberVersion] = newQuorum;
}

/// @dev Change maximum active proposals per member
/// @param newMax New maximum value to set (must be between 1 and 50)
///
/// @notice Max proposals change flow (Checks-Effects):
/// 1. Checks: Validate range (1 to 50 inclusive)
/// 2. Effects: Update maxActiveProposalsPerMember value and emit MaxProposalsPerMemberUpdated event
///
/// @notice Valid range: 1 to 50 (inclusive)
/// @notice Lower values increase security (reduce spam), higher values increase throughput
///
/// @notice Reentrancy protection: Caller (_executeProposal) has nonReentrant guard
function _changeMaxProposals(uint256 newMax) internal {
    // CHECKS: Validate range (1 to 50)
    if (newMax < 1 || newMax > 50) revert InvalidMaxProposals();

    // Update state and emit event
    uint256 oldMax = maxActiveProposalsPerMember;
    maxActiveProposalsPerMember = newMax;

    emit MaxProposalsPerMemberUpdated(oldMax, newMax);
}

// ValidateTransactionWithState is a helper method to check whether a transaction
// is valid according to the pool's internal state checks (balance, nonce, gaps).
//
// This check is public to allow different transaction pools to check the stateful
// rules without duplicating code and running the risk of missed updates.
func ValidateTransactionWithState(tx *types.Transaction, signer types.Signer, opts *ValidationOptionsWithState) error {
	// Ensure the transaction adheres to nonce ordering
	from, err := signer.Sender(tx) // already validated (and cached), but cleaner to check
	if err != nil {
		log.Error("Transaction sender recovery failed", "err", err)
		return err
	}
	// Ensure that neither the sender nor the recipient is blacklisted
	if opts.Config.AnzeonEnabled() {
		if opts.State.IsBlacklisted(from) {
			return &core.ErrBlacklistedAccount{Address: from}
		}
		if to := tx.To(); to != nil && opts.State.IsBlacklisted(*to) {
			return &core.ErrBlacklistedAccount{Address: *to}
		}
	}
	next := opts.State.GetNonce(from)
	if next > tx.Nonce() {
		return fmt.Errorf("%w: next nonce %v, tx nonce %v", core.ErrNonceTooLow, next, tx.Nonce())
	}
	// Ensure the transaction doesn't produce a nonce gap in pools that do not
	// support arbitrary orderings
	if opts.FirstNonceGap != nil {
		if gap := opts.FirstNonceGap(from); gap < tx.Nonce() {
			return fmt.Errorf("%w: tx nonce %v, gapped nonce %v", core.ErrNonceTooHigh, tx.Nonce(), gap)
		}
	}
	// Ensure the transactor has enough funds to cover the transaction costs
	var (
		balance = opts.State.GetBalance(from).ToBig()
		cost    = tx.Cost()
	)
	if tx.Type() == types.FeeDelegateDynamicFeeTxType {
		var (
			txValue         = tx.Value()
			txFeeCost       = tx.FeeCost()
			feePayer        = *tx.FeePayer()
			feePayerBalance = opts.State.GetBalance(feePayer).ToBig()
		)
		// Ensure that the fee payer is not blacklisted
		if opts.Config.AnzeonEnabled() && opts.State.IsBlacklisted(feePayer) {
			return &core.ErrBlacklistedAccount{Address: feePayer}
		}
		if balance.Cmp(txValue) < 0 {
			return fmt.Errorf("%w: balance %v, tx value %v, overshot %v", ErrSenderInsufficientFunds, balance, txValue, new(big.Int).Sub(txValue, balance))
		}
		if feePayerBalance.Cmp(txFeeCost) < 0 {
			return fmt.Errorf("%w: balance %v, fee cost %v, overshot %v", ErrFeePayerInsufficientFunds, feePayerBalance, txFeeCost, new(big.Int).Sub(txFeeCost, feePayerBalance))
		}
	} else {
		if balance.Cmp(cost) < 0 {
			return fmt.Errorf("%w: balance %v, tx cost %v, overshot %v", core.ErrInsufficientFunds, balance, cost, new(big.Int).Sub(cost, balance))
		}
	}

	// EIP-7702: Ensure delegated accounts or accounts with pending authorizations
	// don't exceed their transaction slot limit when adding new transactions.
	// Replacements (same nonce) are allowed without slot limit check.
	if opts.UsedAndLeftSlots != nil && opts.ExistingCost(from, tx.Nonce()) == nil {
		if used, left := opts.UsedAndLeftSlots(from); left <= 0 {
			return fmt.Errorf("%w: pooled %d txs", ErrAccountLimitExceeded, used)
		}
	}

	// go-stablenet skips cumulative balance validation for fee delegation tx compatibility.
	// Fee delegation transactions split costs between sender (value only) and feePayer (gas fees),
	// but ExistingExpenditure callback sums total tx.Cost() which is incompatible with this model.
	// Enabling this validation would incorrectly reject transactions when fee delegation txs exist
	// in the pending pool, as it would compare sender's balance against the full cost (value + gas).
	// Transaction replacement is still supported via legacypool's price bump mechanism.
	/*
		// Ensure the transactor has enough funds to cover for replacements or nonce
		// expansions without overdrafts
		spent := opts.ExistingExpenditure(from)
		if prev := opts.ExistingCost(from, tx.Nonce()); prev != nil {
			bump := new(big.Int).Sub(cost, prev)
			need := new(big.Int).Add(spent, bump)
			if balance.Cmp(need) < 0 {
				return fmt.Errorf("%w: balance %v, queued cost %v, tx bumped %v, overshot %v", core.ErrInsufficientFunds, balance, spent, bump, new(big.Int).Sub(need, balance))
			}
		} else {
			need := new(big.Int).Add(spent, cost)
			if balance.Cmp(need) < 0 {
				return fmt.Errorf("%w: balance %v, queued cost %v, tx cost %v, overshot %v", core.ErrInsufficientFunds, balance, spent, cost, new(big.Int).Sub(need, balance))
			}
			// Transaction takes a new nonce value out of the pool. Ensure it doesn't
			// overflow the number of permitted transactions from a single account
			// (i.e. max cancellable via out-of-bound transaction).
			if used, left := opts.UsedAndLeftSlots(from); left <= 0 {
				return fmt.Errorf("%w: pooled %d txs", ErrAccountLimitExceeded, used)
			}
		}
	*/

	// Cache the Anzeon tip cap to avoid repeated state queries during reheap
	// Only cache if not already set (to preserve original value during reinject)
	if opts.AnzeonTipEnv != nil && tx.GetAnzeonTipCap() == nil {
		tipCap := opts.AnzeonTipEnv.GetAnzeonTipCap(tx)
		tx.SetAnzeonTipCap(tipCap)
	}

	return nil
}

// validateTx checks whether a transaction is valid according to the consensus
// rules and adheres to some heuristic limits of the local node (price and size).
func (p *BlobPool) validateTx(tx *types.Transaction) error {
	// Ensure the transaction adheres to basic pool filters (type, size, tip) and
	// consensus rules
	baseOpts := &txpool.ValidationOptions{
		Config:  p.chain.Config(),
		Accept:  1 << types.BlobTxType,
		MaxSize: txMaxSize,
		MinTip:  p.gasTip.ToBig(),
	}
	if err := txpool.ValidateTransaction(tx, p.head, p.signer, baseOpts); err != nil {
		return err
	}
	// Ensure the transaction adheres to the stateful pool filters (nonce, balance)
	stateOpts := &txpool.ValidationOptionsWithState{
		Config: p.chain.Config(),

		State: p.state,

		FirstNonceGap: func(addr common.Address) uint64 {
			// Nonce gaps are not permitted in the blob pool, the first gap will
			// be the next nonce shifted by however many transactions we already
			// have pooled.
			return p.state.GetNonce(addr) + uint64(len(p.index[addr]))
		},
		UsedAndLeftSlots: func(addr common.Address) (int, int) {
			have := len(p.index[addr])
			if have >= maxTxsPerAccount {
				return have, 0
			}
			return have, maxTxsPerAccount - have
		},
		ExistingExpenditure: func(addr common.Address) *big.Int {
			if spent := p.spent[addr]; spent != nil {
				return spent.ToBig()
			}
			return new(big.Int)
		},
		ExistingCost: func(addr common.Address, nonce uint64) *big.Int {
			next := p.state.GetNonce(addr)
			if uint64(len(p.index[addr])) > nonce-next {
				return p.index[addr][int(tx.Nonce()-next)].costCap.ToBig()
			}
			return nil
		},
	}
	if err := txpool.ValidateTransactionWithState(tx, p.signer, stateOpts); err != nil {
		return err
	}
	if err := p.checkDelegationLimit(tx); err != nil {
		return err
	}
	// If the transaction replaces an existing one, ensure that price bumps are
	// adhered to.
	var (
		from, _ = p.signer.Sender(tx) // already validated above
		next    = p.state.GetNonce(from)
	)
	if uint64(len(p.index[from])) > tx.Nonce()-next {
		// Account can support the replacement, but the price bump must also be met
		prev := p.index[from][int(tx.Nonce()-next)]
		switch {
		case tx.GasFeeCapIntCmp(prev.execFeeCap.ToBig()) <= 0:
			return fmt.Errorf("%w: new tx gas fee cap %v <= %v queued", txpool.ErrReplaceUnderpriced, tx.GasFeeCap(), prev.execFeeCap)
		case tx.GasTipCapIntCmp(prev.execTipCap.ToBig()) <= 0:
			return fmt.Errorf("%w: new tx gas tip cap %v <= %v queued", txpool.ErrReplaceUnderpriced, tx.GasTipCap(), prev.execTipCap)
		case tx.BlobGasFeeCapIntCmp(prev.blobFeeCap.ToBig()) <= 0:
			return fmt.Errorf("%w: new tx blob gas fee cap %v <= %v queued", txpool.ErrReplaceUnderpriced, tx.BlobGasFeeCap(), prev.blobFeeCap)
		}
		var (
			multiplier = uint256.NewInt(100 + p.config.PriceBump)
			onehundred = uint256.NewInt(100)

			minGasFeeCap     = new(uint256.Int).Div(new(uint256.Int).Mul(multiplier, prev.execFeeCap), onehundred)
			minGasTipCap     = new(uint256.Int).Div(new(uint256.Int).Mul(multiplier, prev.execTipCap), onehundred)
			minBlobGasFeeCap = new(uint256.Int).Div(new(uint256.Int).Mul(multiplier, prev.blobFeeCap), onehundred)
		)
		switch {
		case tx.GasFeeCapIntCmp(minGasFeeCap.ToBig()) < 0:
			return fmt.Errorf("%w: new tx gas fee cap %v <= %v queued + %d%% replacement penalty", txpool.ErrReplaceUnderpriced, tx.GasFeeCap(), prev.execFeeCap, p.config.PriceBump)
		case tx.GasTipCapIntCmp(minGasTipCap.ToBig()) < 0:
			return fmt.Errorf("%w: new tx gas tip cap %v <= %v queued + %d%% replacement penalty", txpool.ErrReplaceUnderpriced, tx.GasTipCap(), prev.execTipCap, p.config.PriceBump)
		case tx.BlobGasFeeCapIntCmp(minBlobGasFeeCap.ToBig()) < 0:
			return fmt.Errorf("%w: new tx blob gas fee cap %v <= %v queued + %d%% replacement penalty", txpool.ErrReplaceUnderpriced, tx.BlobGasFeeCap(), prev.blobFeeCap, p.config.PriceBump)
		}
	}
	return nil
}

// ValidateTransaction is a helper method to check whether a transaction is valid
// according to the consensus rules, but does not check state-dependent validation
// (balance, nonce, etc).
//
// This check is public to allow different transaction pools to check the basic
// rules without duplicating code and running the risk of missed updates.
func ValidateTransaction(tx *types.Transaction, head *types.Header, signer types.Signer, opts *ValidationOptions) error {
	// Ensure transactions not implemented by the calling pool are rejected
	if opts.Accept&(1<<tx.Type()) == 0 {
		return fmt.Errorf("%w: tx type %v not supported by this pool", core.ErrTxTypeNotSupported, tx.Type())
	}
	// Before performing any expensive validations, sanity check that the tx is
	// smaller than the maximum limit the pool can meaningfully handle
	if tx.Size() > opts.MaxSize {
		return fmt.Errorf("%w: transaction size %v, limit %v", ErrOversizedData, tx.Size(), opts.MaxSize)
	}
	// Ensure only transactions that have been enabled are accepted
	if !opts.Config.IsBerlin(head.Number) && tx.Type() != types.LegacyTxType {
		return fmt.Errorf("%w: type %d rejected, pool not yet in Berlin", core.ErrTxTypeNotSupported, tx.Type())
	}
	if !opts.Config.IsLondon(head.Number) && tx.Type() == types.DynamicFeeTxType {
		return fmt.Errorf("%w: type %d rejected, pool not yet in London", core.ErrTxTypeNotSupported, tx.Type())
	}
	if !opts.Config.IsApplepie(head.Number) && tx.Type() == types.FeeDelegateDynamicFeeTxType {
		return fmt.Errorf("%w: type %d rejected, pool not yet in Applepie", core.ErrTxTypeNotSupported, tx.Type())
	}
	if !opts.Config.IsCancun(head.Number, head.Time) && tx.Type() == types.BlobTxType {
		return fmt.Errorf("%w: type %d rejected, pool not yet in Cancun", core.ErrTxTypeNotSupported, tx.Type())
	}
	if !opts.Config.AnzeonEnabled() && tx.Type() == types.SetCodeTxType {
		return fmt.Errorf("%w: type %d rejected, pool not yet in Anzeon", core.ErrTxTypeNotSupported, tx.Type())
	}
	// Check whether the init code size has been exceeded
	if opts.Config.IsShanghai(head.Number, head.Time) && tx.To() == nil && len(tx.Data()) > params.MaxInitCodeSize {
		return fmt.Errorf("%w: code size %v, limit %v", core.ErrMaxInitCodeSizeExceeded, len(tx.Data()), params.MaxInitCodeSize)
	}
	// Transactions can't be negative. This may never happen using RLP decoded
	// transactions but may occur for transactions created using the RPC.
	if tx.Value().Sign() < 0 {
		return ErrNegativeValue
	}
	// Ensure the transaction doesn't exceed the current block limit gas
	if head.GasLimit < tx.Gas() {
		return ErrGasLimit
	}
	// Sanity check for extremely large numbers (supported by RLP or RPC)
	if tx.GasFeeCap().BitLen() > 256 {
		return core.ErrFeeCapVeryHigh
	}
	if tx.GasTipCap().BitLen() > 256 {
		return core.ErrTipVeryHigh
	}
	// Ensure gasFeeCap is greater than or equal to gasTipCap
	if tx.GasFeeCapIntCmp(tx.GasTipCap()) < 0 {
		return core.ErrTipAboveFeeCap
	}
	// Make sure the transaction is signed properly
	if _, err := types.Sender(signer, tx); err != nil {
		return ErrInvalidSender
	}
	// Ensure the transaction has more gas than the bare minimum needed to cover
	// the transaction metadata
	intrGas, err := core.IntrinsicGas(tx.Data(), tx.AccessList(), tx.SetCodeAuthorizations(), tx.To() == nil, true, opts.Config.IsIstanbul(head.Number), opts.Config.IsShanghai(head.Number, head.Time))
	if err != nil {
		return err
	}
	if tx.Gas() < intrGas {
		return fmt.Errorf("%w: gas %v, minimum needed %v", core.ErrIntrinsicGas, tx.Gas(), intrGas)
	}
	// Ensure the gasprice is high enough to cover the requirement of the calling pool
	if tx.GasTipCapIntCmp(opts.MinTip) < 0 {
		return fmt.Errorf("%w: gas tip cap %v, minimum needed %v", ErrUnderpriced, tx.GasTipCap(), opts.MinTip)
	}
	if opts.Config.IsLondon(head.Number) && opts.Config.AnzeonEnabled() {
		minBaseFee := opts.Config.MinBaseFee()
		minFee := new(big.Int).Add(minBaseFee, opts.MinTip)

		// NOTE: For LegacyTx and AccessListTx, GasFeeCap() returns GasPrice.
		// So this rule also enforces gasPrice >= MinBaseFee + MinTip for legacy-style txs.
		if tx.GasFeeCapIntCmp(minFee) < 0 {
			return fmt.Errorf("%w: gas fee cap %v, minimum needed %v", ErrUnderpriced, tx.GasFeeCap(), minFee)
		}
	}

	if tx.Type() == types.FeeDelegateDynamicFeeTxType {
		// Make sure the transaction is signed properly.
		if tx.FeePayer() == nil {
			return ErrInvalidFeePayer
		}
		feePayer, err := types.FeePayer(types.NewFeeDelegateSigner(opts.Config.ChainID), tx)
		if err != nil || *tx.FeePayer() != feePayer {
			return ErrInvalidFeePayer
		}
	}

	if tx.Type() == types.SetCodeTxType {
		if len(tx.SetCodeAuthorizations()) == 0 {
			return fmt.Errorf("set code tx must have at least one authorization tuple")
		}
	}

	if tx.Type() == types.BlobTxType {
		// Ensure the blob fee cap satisfies the minimum blob gas price
		if tx.BlobGasFeeCapIntCmp(blobTxMinBlobGasPrice) < 0 {
			return fmt.Errorf("%w: blob fee cap %v, minimum needed %v", ErrUnderpriced, tx.BlobGasFeeCap(), blobTxMinBlobGasPrice)
		}
		sidecar := tx.BlobTxSidecar()
		if sidecar == nil {
			return fmt.Errorf("missing sidecar in blob transaction")
		}
		// Ensure the number of items in the blob transaction and various side
		// data match up before doing any expensive validations
		hashes := tx.BlobHashes()
		if len(hashes) == 0 {
			return fmt.Errorf("blobless blob transaction")
		}
		if len(hashes) > params.MaxBlobGasPerBlock/params.BlobTxBlobGasPerBlob {
			return fmt.Errorf("too many blobs in transaction: have %d, permitted %d", len(hashes), params.MaxBlobGasPerBlock/params.BlobTxBlobGasPerBlob)
		}
		// Ensure commitments, proofs and hashes are valid
		if err := validateBlobSidecar(hashes, sidecar); err != nil {
			return err
		}
	}
	return nil
}

// ValidationOptionsWithState define certain differences between stateful transaction
// validation across the different pools without having to duplicate those checks.
type ValidationOptionsWithState struct {
	Config *params.ChainConfig // Chain configuration to selectively validate based on current fork rules

	State *state.StateDB // State database to check nonces and balances against

	// FirstNonceGap is an optional callback to retrieve the first nonce gap in
	// the list of pooled transactions of a specific account. If this method is
	// set, nonce gaps will be checked and forbidden. If this method is not set,
	// nonce gaps will be ignored and permitted.
	FirstNonceGap func(addr common.Address) uint64

	// UsedAndLeftSlots is an optional callback to retrieve the number of tx slots
	// used and the number still permitted for an account. New transactions will
	// be rejected once the number of remaining slots reaches zero.
	UsedAndLeftSlots func(addr common.Address) (int, int)

	// ExistingExpenditure is a mandatory callback to retrieve the cumulative
	// cost of the already pooled transactions to check for overdrafts.
	ExistingExpenditure func(addr common.Address) *big.Int

	// ExistingCost is a mandatory callback to retrieve an already pooled
	// transaction's cost with the given nonce to check for overdrafts.
	ExistingCost func(addr common.Address, nonce uint64) *big.Int

	// AnzeonTipEnv is an optional environment for computing and caching
	// the Anzeon gas tip cap during validation to avoid repeated state queries during reheap.
	AnzeonTipEnv types.AnzeonGasTipEnv
}

// validateTx checks whether a transaction is valid according to the consensus
// rules and adheres to some heuristic limits of the local node (price and size).
func (pool *LegacyPool) validateTx(tx *types.Transaction, local bool) error {
	opts := &txpool.ValidationOptionsWithState{
		Config: pool.chainconfig,

		State: pool.currentState,

		FirstNonceGap:    nil, // Pool allows arbitrary arrival order, don't invalidate nonce gaps
		UsedAndLeftSlots: nil, // Pool has own mechanism to limit the number of transactions
		ExistingExpenditure: func(addr common.Address) *big.Int {
			if list := pool.pending[addr]; list != nil {
				return list.totalcost.ToBig()
			}
			return new(big.Int)
		},
		ExistingCost: func(addr common.Address, nonce uint64) *big.Int {
			if list := pool.pending[addr]; list != nil {
				if tx := list.txs.Get(nonce); tx != nil {
					return tx.Cost()
				}
			}
			return nil
		},
		AnzeonTipEnv: pool.anzeonTipEnv, // Enable caching of Anzeon tip cap during validation
	}
	if err := txpool.ValidateTransactionWithState(tx, pool.signer, opts); err != nil {
		return err
	}
	return pool.validateAuth(tx)
}

//   - Analogously, if the pool is full, the consideration price of a new tx for
//     evicting an old one is the smallest price in the entire nonce-sequence of
//     the account. This avoids malicious users DoSing the pool with seemingly
//     high paying transactions hidden behind a low-paying blocked one.
//
//   - Since blob transactions have 3 price parameters: execution tip, execution
//     fee cap and data fee cap, there's no singular parameter to create a total
//     price ordering on. What's more, since the base fee and blob fee can move
//     independently of one another, there's no pre-defined way to combine them
//     into a stable order either. This leads to a multi-dimensional problem to
//     solve after every block.
//
//   - The first observation is that comparing 1559 base fees or 4844 blob fees
//     needs to happen in the context of their dynamism. Since these fees jump
//     up or down in ~1.125 multipliers (at max) across blocks, comparing fees
//     in two transactions should be based on log1.125(fee) to eliminate noise.
//
//   - The second observation is that the basefee and blobfee move independently,
//     so there's no way to split mixed txs on their own (A has higher base fee,
//     B has higher blob fee). Rather than look at the absolute fees, the useful
//     metric is the max time it can take to exceed the transaction's fee caps.
//     Specifically, we're interested in the number of jumps needed to go from
//     the current fee to the transaction's cap:
//
//     jumps = log1.125(txfee) - log1.125(basefee)
//
//   - The third observation is that the base fee tends to hover around rather
//     than swing wildly. The number of jumps needed from the current fee starts
//     to get less relevant the higher it is. To remove the noise here too, the
//     pool will use log(jumps) as the delta for comparing transactions.
//
//     delta = sign(jumps) * log(abs(jumps))
//
//   - To establish a total order, we need to reduce the dimensionality of the
//     two base fees (log jumps) to a single value. The interesting aspect from
//     the pool's perspective is how fast will a tx get executable (fees going
//     down, crossing the smaller negative jump counter) or non-executable (fees
//     going up, crossing the smaller positive jump counter). As such, the pool
//     cares only about the min of the two delta values for eviction priority.
//
//     priority = min(deltaBasefee, deltaBlobfee)
//
//   - The above very aggressive dimensionality and noise reduction should result
//     in transaction being grouped into a small number of buckets, the further
//     the fees the larger the buckets. This is good because it allows us to use
//     the miner tip meaningfully as a splitter.
//
//   - For the scenario where the pool does not contain non-executable blob txs
//     anymore, it does not make sense to grant a later eviction priority to txs
//     with high fee caps since it could enable pool wars. As such, any positive
//     priority will be grouped together.
//
//     priority = min(deltaBasefee, deltaBlobfee, 0)
//
// Optimisation tradeoffs:
//
//   - Eviction relies on 3 fee minimums per account (exec tip, exec cap and blob
//     cap). Maintaining these values across all transactions from the account is
//     problematic as each transaction replacement or inclusion would require a
//     rescan of all other transactions to recalculate the minimum. Instead, the
//     pool maintains a rolling minimum across the nonce range. Updating all the
//     minimums will need to be done only starting at the swapped in/out nonce
//     and leading up to the first no-change.
type BlobPool struct {
	config         Config                    // Pool configuration
	reserver       txpool.Reserver           // Address reserver to ensure exclusivity across subpools
	hasPendingAuth func(common.Address) bool // Determine whether the specified address has a pending 7702-auth

	store  billy.Database // Persistent data store for the tx metadata and blobs
	stored uint64         // Useful data size of all transactions on disk
	limbo  *limbo         // Persistent data store for the non-finalized blobs

	signer types.Signer // Transaction signer to use for sender recovery
	chain  BlockChain   // Chain object to access the state through

	head   *types.Header  // Current head of the chain
	state  *state.StateDB // Current state at the head of the chain
	gasTip *uint256.Int   // Currently accepted minimum gas tip

	lookup map[common.Hash]uint64           // Lookup table mapping hashes to tx billy entries
	index  map[common.Address][]*blobTxMeta // Blob transactions grouped by accounts, sorted by nonce
	spent  map[common.Address]*uint256.Int  // Expenditure tracking for individual accounts
	evict  *evictHeap                       // Heap of cheapest accounts for eviction when full

	discoverFeed event.Feed // Event feed to send out new tx events on pool discovery (reorg excluded)
	insertFeed   event.Feed // Event feed to send out new tx events on pool inclusion (reorg included)

	lock sync.RWMutex // Mutex protecting the pool during reorg handling
}

// recheck verifies the pool's content for a specific account and drops anything
// that does not fit anymore (dangling or filled nonce, overdraft).
func (p *BlobPool) recheck(addr common.Address, inclusions map[common.Hash]uint64) {
	// Sort the transactions belonging to the account so reinjects can be simpler
	txs := p.index[addr]
	if inclusions != nil && txs == nil { // during reorgs, we might find new accounts
		return
	}
	sort.Slice(txs, func(i, j int) bool {
		return txs[i].nonce < txs[j].nonce
	})
	// If there is a gap between the chain state and the blob pool, drop
	// all the transactions as they are non-executable. Similarly, if the
	// entire tx range was included, drop all.
	var (
		next   = p.state.GetNonce(addr)
		gapped = txs[0].nonce > next
		filled = txs[len(txs)-1].nonce < next
	)
	if gapped || filled {
		var (
			ids    []uint64
			nonces []uint64
		)
		for i := 0; i < len(txs); i++ {
			ids = append(ids, txs[i].id)
			nonces = append(nonces, txs[i].nonce)

			p.stored -= uint64(txs[i].size)
			delete(p.lookup, txs[i].hash)

			// Included transactions blobs need to be moved to the limbo
			if filled && inclusions != nil {
				p.offload(addr, txs[i].nonce, txs[i].id, inclusions)
			}
		}
		delete(p.index, addr)
		delete(p.spent, addr)
		if inclusions != nil { // only during reorgs will the heap be initialized
			heap.Remove(p.evict, p.evict.index[addr])
		}
		p.reserver.Release(addr)

		if gapped {
			log.Warn("Dropping dangling blob transactions", "from", addr, "missing", next, "drop", nonces, "ids", ids)
			dropDanglingMeter.Mark(int64(len(ids)))
		} else {
			log.Trace("Dropping filled blob transactions", "from", addr, "filled", nonces, "ids", ids)
			dropFilledMeter.Mark(int64(len(ids)))
		}
		for _, id := range ids {
			if err := p.store.Delete(id); err != nil {
				log.Error("Failed to delete blob transaction", "from", addr, "id", id, "err", err)
			}
		}
		return
	}
	// If there is overlap between the chain state and the blob pool, drop
	// anything below the current state
	if txs[0].nonce < next {
		var (
			ids    []uint64
			nonces []uint64
		)
		for txs[0].nonce < next {
			ids = append(ids, txs[0].id)
			nonces = append(nonces, txs[0].nonce)

			p.spent[addr] = new(uint256.Int).Sub(p.spent[addr], txs[0].costCap)
			p.stored -= uint64(txs[0].size)
			delete(p.lookup, txs[0].hash)

			// Included transactions blobs need to be moved to the limbo
			if inclusions != nil {
				p.offload(addr, txs[0].nonce, txs[0].id, inclusions)
			}
			txs = txs[1:]
		}
		log.Trace("Dropping overlapped blob transactions", "from", addr, "overlapped", nonces, "ids", ids, "left", len(txs))
		dropOverlappedMeter.Mark(int64(len(ids)))

		for _, id := range ids {
			if err := p.store.Delete(id); err != nil {
				log.Error("Failed to delete blob transaction", "from", addr, "id", id, "err", err)
			}
		}
		p.index[addr] = txs
	}
	// Iterate over the transactions to initialize their eviction thresholds
	// and to detect any nonce gaps
	txs[0].evictionExecTip = txs[0].execTipCap
	txs[0].evictionExecFeeJumps = txs[0].basefeeJumps
	txs[0].evictionBlobFeeJumps = txs[0].blobfeeJumps

	for i := 1; i < len(txs); i++ {
		// If there's no nonce gap, initialize the eviction thresholds as the
		// minimum between the cumulative thresholds and the current tx fees
		if txs[i].nonce == txs[i-1].nonce+1 {
			txs[i].evictionExecTip = txs[i-1].evictionExecTip
			if txs[i].evictionExecTip.Cmp(txs[i].execTipCap) > 0 {
				txs[i].evictionExecTip = txs[i].execTipCap
			}
			txs[i].evictionExecFeeJumps = txs[i-1].evictionExecFeeJumps
			if txs[i].evictionExecFeeJumps > txs[i].basefeeJumps {
				txs[i].evictionExecFeeJumps = txs[i].basefeeJumps
			}
			txs[i].evictionBlobFeeJumps = txs[i-1].evictionBlobFeeJumps
			if txs[i].evictionBlobFeeJumps > txs[i].blobfeeJumps {
				txs[i].evictionBlobFeeJumps = txs[i].blobfeeJumps
			}
			continue
		}
		// Sanity check that there's no double nonce. This case would generally
		// be a coding error, so better know about it.
		//
		// Also, Billy behind the blobpool does not journal deletes. A process
		// crash would result in previously deleted entities being resurrected.
		// That could potentially cause a duplicate nonce to appear.
		if txs[i].nonce == txs[i-1].nonce {
			id := p.lookup[txs[i].hash]

			log.Error("Dropping repeat nonce blob transaction", "from", addr, "nonce", txs[i].nonce, "id", id)
			dropRepeatedMeter.Mark(1)

			p.spent[addr] = new(uint256.Int).Sub(p.spent[addr], txs[i].costCap)
			p.stored -= uint64(txs[i].size)
			delete(p.lookup, txs[i].hash)

			if err := p.store.Delete(id); err != nil {
				log.Error("Failed to delete blob transaction", "from", addr, "id", id, "err", err)
			}
			txs = append(txs[:i], txs[i+1:]...)
			p.index[addr] = txs

			i--
			continue
		}
		// Otherwise if there's a nonce gap evict all later transactions
		var (
			ids    []uint64
			nonces []uint64
		)
		for j := i; j < len(txs); j++ {
			ids = append(ids, txs[j].id)
			nonces = append(nonces, txs[j].nonce)

			p.spent[addr] = new(uint256.Int).Sub(p.spent[addr], txs[j].costCap)
			p.stored -= uint64(txs[j].size)
			delete(p.lookup, txs[j].hash)
		}
		txs = txs[:i]

		log.Error("Dropping gapped blob transactions", "from", addr, "missing", txs[i-1].nonce+1, "drop", nonces, "ids", ids)
		dropGappedMeter.Mark(int64(len(ids)))

		for _, id := range ids {
			if err := p.store.Delete(id); err != nil {
				log.Error("Failed to delete blob transaction", "from", addr, "id", id, "err", err)
			}
		}
		p.index[addr] = txs
		break
	}
	// Ensure that there's no over-draft, this is expected to happen when some
	// transactions get included without publishing on the network
	var (
		balance = p.state.GetBalance(addr)
		spent   = p.spent[addr]
	)
	if spent.Cmp(balance) > 0 {
