// CallEngineSpecific implements consensus.Engine
func (sb *Backend) CallEngineSpecific(method string, args ...interface{}) interface{} {
	switch method {
	case "Start":
		if len(args) != 4 {
			return wbftcommon.ErrInvalidSpecificCall
		}
		chain, ok := args[0].(consensus.ChainHeaderReader)
		if !ok {
			return wbftcommon.ErrInvalidSpecificCall
		}
		currentBlock, ok := args[1].(func() *types.Block)
		if !ok {
			return wbftcommon.ErrInvalidSpecificCall
		}
		hasBadBlock, ok := args[2].(func(db ethdb.Reader, hash common.Hash) bool)
		if !ok {
			return wbftcommon.ErrInvalidSpecificCall
		}
		notifyNewRound, ok := args[3].(func(waitTime time.Duration, round *big.Int))
		if !ok {
			return wbftcommon.ErrInvalidSpecificCall
		}
		if sb.coreStarted {
			_ = sb.Stop()
		}
		return sb.Start(chain, currentBlock, hasBadBlock, notifyNewRound)
	case "InheritExtra":
		if len(args) != 3 {
			return wbftcommon.ErrInvalidSpecificCall
		}

		var gasTip *big.Int

		parent, ok := args[0].(*types.Header)
		if !ok {
			return wbftcommon.ErrInvalidSpecificCall
		}
		header, ok := args[1].(*types.Header)
		if !ok {
			return wbftcommon.ErrInvalidSpecificCall
		}
		tip, ok := args[2].(*big.Int)
		if !ok || tip == nil {
			return wbftcommon.ErrInvalidSpecificCall
		}
		gasTip = tip

		extra, err := types.ExtractWBFTExtra(parent)
		if err != nil {
			return err
		}

		if parent.Number.Sign() > 0 {
			if extra.PreparedSeal == nil {
				return wbftcommon.ErrEmptyPreparedSeals
			} else if extra.CommittedSeal == nil {
				// TODO : what if there is not committedSeal that node collected?
				return wbftcommon.ErrEmptyCommittedSeals
			}
		}

		prevPreparedSeal := extra.PreparedSeal
		prevCommittedSeal := extra.CommittedSeal

		// add gas tip and last block committers information to the header extraData.
		// - gastip is written via WriteGasTip()
		// - prepared seals (prevPreparedSeal) are written via WritePrevSeals()
		// - committed seals (prevCommittedSeal) are written via WritePrevSeals()
		// Note: Validators are defined in the genesis block.
		wbftengine.ApplyHeaderWBFTExtra(
			header,
			sb.Engine().WriteRandao(sb.chain.Config(), header),
			wbftengine.WritePrevSeals(extra.Round, prevPreparedSeal, prevCommittedSeal),
			wbftengine.WriteGasTip(gasTip))
		return nil

	case "SetMixDigest":
		if len(args) != 2 {
			return wbftcommon.ErrInvalidSpecificCall
		}
		parent, ok := args[0].(*types.Header)
		if !ok {
			return wbftcommon.ErrInvalidSpecificCall
		}
		header, ok := args[1].(*types.Header)
		if !ok {
			return wbftcommon.ErrInvalidSpecificCall
		}
		extra, err := types.ExtractWBFTExtra(header)
		if err != nil {
			return err
		}

		header.MixDigest = wbftengine.CalculateRandaoMix(parent.MixDigest, extra.RandaoReveal)
		return nil

	case "NewChainHead":
		return sb.NewChainHead()

	case "SetCoinbase":
		header, ok := args[0].(*types.Header)
		if !ok {
			return wbftcommon.ErrInvalidSpecificCall
		}
		header.Coinbase = sb.Engine().Address()
		return nil

	default:
		return wbftcommon.ErrInvalidSpecificCall
	}
}

// Finalize runs any post-transaction state modifications (e.g. block rewards)
// and assembles the final block.
//
// Note, the block header and state database might be updated to reflect any
// consensus rules that happen at finalization (e.g. block rewards).
func (sb *Backend) Finalize(chain consensus.ChainHeaderReader, header *types.Header, state *state.StateDB, txs []*types.Transaction, uncles []*types.Header, _ []*types.Withdrawal) error {
	return sb.Engine().Finalize(chain, header, state, txs, uncles)
}

        // Calculate rejection threshold: maximum rejections before approval becomes impossible
        // Example: 5 members, quorum=3 → maxRejections=2 (if rejected>2, cannot reach quorum)
        uint32 maxRejections = uint32(snapshot.length) - proposal.requiredApprovals;
        if (newRejected > maxRejections) {
            _finalizeProposal(proposalId, ProposalStatus.Rejected);
            emit ProposalRejected(proposalId, msg.sender, proposal.approved, newRejected);
        }
    }
}

/// @dev Execute approved proposal with automatic retry tracking
/// @param proposalId The proposal ID to execute
/// @param markFailedOnError Failure handling mode:
///        - true: Terminal execution, proposal marked Failed on error (used by executeWithFailure)
///        - false: Retry-enabled, proposal stays Approved on error (used by executeProposal, auto-execute)
/// @return success True if execution succeeded
///
/// @notice Execution flow (Checks-Effects-Interactions):
/// 1. Checks: Validate proposal state, quorum, expiry, and retry limit
/// 2. Effects: Increment execution count before external call
/// 3. Interactions: Execute action via _executeInternalAction
/// 4. Effects: Update proposal status based on result
///
/// @notice Retry limit: MAX_RETRY_COUNT (3 attempts total)
/// - All execution attempts (both executeProposal and executeWithFailure) are subject to retry limit
/// - After 3 execution attempts, any further execution will auto-transition to Failed status
/// - Auto-fail behavior ensures resources are cleaned up via _finalizeProposal
/// - markFailedOnError only affects immediate execution failure: false keeps Approved for retry, true marks as Failed
///
/// @notice Reentrancy protection: nonReentrant modifier prevents same-function reentry
/// @notice Security consideration: State changes occur after _executeInternalAction call
///         Derived contracts must avoid external calls in _executeCustomAction to prevent
///         cross-function reentrancy attacks
function _executeProposal(uint256 proposalId, bool markFailedOnError) internal nonReentrant returns (bool success) {
    // CHECKS: Validate proposal state
    if (proposalId == 0 || proposalId > currentProposalId) revert InvalidProposal();

    Proposal storage proposal = proposals[proposalId];

    if (proposal.status != ProposalStatus.Approved) revert ProposalNotExecutable();
    if (proposal.approved < proposal.requiredApprovals) revert InsufficientApprovals();

    // Handle expiry gracefully (update state and return false)
    // Note: Execution attempt on expired proposal will trigger expiry state transition.
    // Returns false to indicate execution did not succeed, but state changes persist.
    if (block.timestamp > proposal.createdAt + proposalExpiry) {
        _finalizeProposal(proposalId, ProposalStatus.Expired);
        emit ProposalExpired(proposalId, msg.sender);
        return false;
    }

    // Check retry limit and auto-fail if reached
    if (proposalExecutionCount[proposalId] >= MAX_RETRY_COUNT) {
        _finalizeProposal(proposalId, ProposalStatus.Failed);
        emit ProposalFailed(proposalId, msg.sender, bytes("Max retry count reached"));
        return false;
    }

    // Increment execution count (rolls back on revert)
    proposalExecutionCount[proposalId]++;

    // Execute action (may call derived contract's _executeCustomAction)
    success = _executeInternalAction(proposal.actionType, proposal.callData);

    // Update proposal state based on execution result
    if (success) {
        _finalizeProposal(proposalId, ProposalStatus.Executed);
        emit ProposalExecuted(proposalId, msg.sender, true);
    } else {
        if (markFailedOnError) {
            // Terminal execution: mark as Failed
            _finalizeProposal(proposalId, ProposalStatus.Failed);
        } else {
            // Retry-enabled: keep as Approved for retry
            proposal.status = ProposalStatus.Approved;
        }
        emit ProposalExecuted(proposalId, msg.sender, false);
    }
}

